        {
            GRGEN_LIBGR.IMatchesExact<Rule_initMvmt.IMatch_initMvmt> matches = DynamicMatch((GRGEN_LGSP.LGSPActionExecutionEnvironment)actionEnv, 1);
            if(matches.Count <= 0) return false;
            
