        public bool ApplyMinMax(GRGEN_LIBGR.IActionExecutionEnvironment actionEnv, int min, int max)
        {
            GRGEN_LIBGR.IMatchesExact<Rule_initMvmt.IMatch_initMvmt> matches;
            
            for(int i = 0; i < max; i++)
            {
